const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Define the Eastern Tropical Pacific region (similar to Nino 1+2 and 3 regions)
  const easternPacific = ee.Geometry.Rectangle([-120, -5, -80, 5]);

  // Define the time periods
  const comparisonDateStart = '2021-11-01';
  const comparisonDateEnd = '2021-11-30';
  const climatologyStart = '1991-01-01'; // 30-year baseline
  const climatologyEnd = '2020-12-31';
  const month = 11; // November

  // 2. Data Acquisition
  const sstCollection = ee.ImageCollection('NOAA/CDR/OISST/V2.1').select('sst');

  // Get data for November 2021
  const sst2021 = sstCollection.filterDate(comparisonDateStart, comparisonDateEnd);

  // Get data for the long-term November average (1991-2020)
  const sstLongTerm = sstCollection
    .filterDate(climatologyStart, climatologyEnd)
    .filter(ee.Filter.calendarRange(month, month, 'month'));

  // 3. Data Availability Check
  const count2021 = sst2021.size().getInfo();
  const countLongTerm = sstLongTerm.size().getInfo();

  if (count2021 === 0 || countLongTerm === 0) {
    console.log(`Image count for Nov 2021: ${count2021}`);
    console.log(`Image count for Nov 1991-2020: ${countLongTerm}`);
    console.log('Empty Collection: No images found for one or both periods.');
    console.log('A');
    return;
  }

  // 4. Processing and Calculation
  // Create mean composites for each period
  const meanSST2021Image = sst2021.mean();
  const meanSSTLongTermImage = sstLongTerm.mean();

  // Define reducer parameters
  const reduceArgs = {
    reducer: ee.Reducer.mean(),
    geometry: easternPacific,
    scale: 30000, // Use a coarse scale appropriate for the data resolution and region size
    maxPixels: 1e9
  };

  // Calculate the mean SST for the region for both periods
  const sst2021Result = meanSST2021Image.reduceRegion(reduceArgs).get('sst');
  const sstLongTermResult = meanSSTLongTermImage.reduceRegion(reduceArgs).get('sst');

  // Evaluate the results
  const sst2021Value = sst2021Result.getInfo();
  const sstLongTermValue = sstLongTermResult.getInfo();

  // 5. Validation and Final Answer
  if (sst2021Value === null || sstLongTermValue === null) {
      console.log(`Nov 2021 SST: ${sst2021Value}`);
      console.log(`Long-term Nov SST: ${sstLongTermValue}`);
      console.log('Calculation resulted in null.');
      console.log('C3');
      return;
  }

  // Convert from Kelvin to Celsius for better readability (SST is in 100*Kelvin)
  const sst2021Celsius = (sst2021Value / 100) - 273.15;
  const sstLongTermCelsius = (sstLongTermValue / 100) - 273.15;

  console.log(`Image count for Nov 2021: ${count2021}`);
  console.log(`Image count for Nov 1991-2020: ${countLongTerm}`);
  console.log(`Average SST for Nov 2021: ${sst2021Celsius.toFixed(2)} C`);
  console.log(`Long-term (1991-2020) average SST for Nov: ${sstLongTermCelsius.toFixed(2)} C`);

  // Compare the values and provide the answer
  if (sst2021Celsius < sstLongTermCelsius) {
    console.log('November 2021 was cooler than the long-term average.');
    console.log('A');
  } else {
    console.log('November 2021 was not cooler than the long-term average.');
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(e => {
  console.error(e);
  console.log('D');
});
